<script setup>
import {computed,ref,onMounted,nextTick,onBeforeUnmount,watch} from 'vue'
import {ArrowLeft,ArrowRight,Plus,Users,Upload,Webhook,Settings2,Save,Trash2,RefreshCw,Copy,Check,Download,Search,X,UserPlus,Link2,FlaskConical} from 'lucide-vue-next'
const emit=defineEmits(['changed'])
const catalog=ref({lists:[],can_manage:false}),detail=ref(null),tab=ref('contacts'),busy=ref(false),error=ref(''),notice=ref(''),listSearch=ref(''),memberSearch=ref(''),creating=ref(false),newList=ref({name:'',kind:'automation'})
const edit=ref(null),contact=ref({}),file=ref(null),delimiter=ref(';'),inspection=ref(null),columns=ref({}),batch=ref(null),csvConsent=ref(false),csvEvidence=ref(''),csvSource=ref('Importação CSV')
const drawer=ref(''),drawerEl=ref(null),candidates=ref(null),candidateSearch=ref(''),chosen=ref([]);let returnFocus=null,draftBaseline='',bodyOverflow=null
const hook=ref(null),secret=ref(''),sample=ref(''),validated=ref(null)
const kindLabel=k=>k==='voice'?'Voz e WhatsApp':'Automação MA'
const baseFields=[{key:'name',label:'Nome'},{key:'phone',label:'Telefone'},{key:'email',label:'E-mail'},{key:'source',label:'Origem'},{key:'crm_contact_id',label:'ID no CRM'},{key:'consent',label:'Autorização (true/false)'},{key:'consent_evidence',label:'Evidência da autorização'}]
const targets=computed(()=>[...baseFields,...(detail.value?.list.fields||[]).map(f=>({key:'fields.'+f.key,label:f.label+' · adicional'}))])
const filtered=computed(()=>catalog.value.lists.filter(l=>l.name.toLowerCase().includes(listSearch.value.toLowerCase())))
const path=computed(()=>'/api/lists/'+detail.value.list.kind+'/'+detail.value.list.id)
async function api(url,method='GET',body){const form=body instanceof FormData;const r=await fetch(url,{method,headers:{Accept:'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content,...(!form?{'Content-Type':'application/json'}:{})},...(body?{body:form?body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw new Error(d.errors?Object.values(d.errors).flat().join(' · '):d.message||'Não foi possível concluir.');return d}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function load(){catalog.value=await api('/api/lists')}
function newContact(){contact.value={name:'',phone:'',email:'',source:'Cadastro manual',crm_contact_id:'',consent:false,consent_evidence:'',fields:{}}}
async function select(l){detail.value=await api('/api/lists/'+l.kind+'/'+l.id);edit.value=JSON.parse(JSON.stringify(detail.value.list));tab.value='contacts';newContact();batch.value=null;inspection.value=null;file.value=null;hook.value=null;secret.value='';memberSearch.value='';error.value='';notice.value=''}
async function reload(page=1){detail.value=await api(path.value+'?'+new URLSearchParams({page,search:memberSearch.value}));await load();emit('changed')}
async function create(){const l=await api('/api/lists','POST',newList.value);creating.value=false;newList.value={name:'',kind:'automation'};await load();await select(l);emit('changed')}
async function saveContact(){const result=await api(path.value+'/contacts','POST',{data:contact.value});await reload();newContact();draftBaseline=draft();notice.value=result.membership_removed?'Este contato já foi retirado da lista. Use Reincluir para restaurar a participação.':result.preserved?'Contato existente vinculado. Dados e autorizações anteriores foram preservados.':'Contato cadastrado e adicionado à lista.'}
async function member(c,restore=false){if(!window.confirm(restore?'Reincluir este contato na lista, preservando bloqueios e histórico?':'Retirar este contato apenas desta lista? O cadastro e o histórico serão preservados.'))return;await api(path.value+'/contacts/'+c.id+(restore?'/restore':''),restore?'POST':'DELETE',{});await reload();notice.value=restore?'Contato reincluído; autorizações e bloqueios foram preservados.':'Contato retirado da lista.'}
function addField(){edit.value.fields.push({key:'campo_'+(edit.value.fields.length+1),label:'',type:'text',required:false})}
async function saveFields(){await api(path.value,'PUT',{revision:edit.value.revision,name:edit.value.name,fields:edit.value.fields});await reload();edit.value=JSON.parse(JSON.stringify(detail.value.list));inspection.value=null;batch.value=null;draftBaseline=draft();notice.value='Lista e campos salvos.'}
function fileBody(){const d=new FormData();d.append('file',file.value);d.append('delimiter',delimiter.value);return d}
async function inspect(){batch.value=null;inspection.value=null;if(!file.value)return;inspection.value=await api(path.value+'/csv/inspect','POST',fileBody());const aliases={name:['nome','name'],phone:['telefone','phone','celular'],email:['email','e-mail'],source:['origem','source'],crm_contact_id:['id_crm','crm_contact_id'],consent:['consent','autorizado','autorizacao'],consent_evidence:['consent_evidence','evidencia']};columns.value=Object.fromEntries(targets.value.map(t=>[t.key,inspection.value.headers.find(h=>(aliases[t.key]||[t.key.replace('fields.','')]).includes(h.toLowerCase()))||'']))}
async function preview(){const d=fileBody();d.append('mapping',JSON.stringify(Object.entries(columns.value).filter(([,source])=>source).map(([target,source])=>({source,target}))));d.append('source',csvSource.value);d.append('consent',csvConsent.value?'1':'0');d.append('consent_evidence',csvEvidence.value);batch.value=await api(path.value+'/csv/preview','POST',d)}
async function commit(){batch.value=await api(path.value+'/imports/'+batch.value.id+'/commit','POST',{});await reload();notice.value='Importação concluída. Confira o resumo abaixo.'}
function download(){const headers=['nome','telefone','email',...(detail.value?.list.fields||[]).map(f=>f.key)];const quote=s=>'"'+String(s).replaceAll('"','""')+'"';const blob=new Blob(['\uFEFF'+headers.map(quote).join(';')+'\r\n'],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='modelo-contatos.csv';a.click();URL.revokeObjectURL(url)}
function editHook(h=null){secret.value='';validated.value=null;hook.value=h?JSON.parse(JSON.stringify({...h,rotate:false})):{name:'Entrada de contatos',active:true,revision:0,rotate:false,mapping:[{source:'cliente.nome',target:'name'},{source:'cliente.telefone',target:'phone'},{source:'cliente.email',target:'email'}]};sample.value=JSON.stringify({cliente:{nome:'Ana Souza',telefone:'+5511999990001',email:'ana@example.test'}},null,2);draftBaseline=draft()}
async function saveHook(){const d=await api(path.value+'/webhooks'+(hook.value.id?'/'+hook.value.id:''),hook.value.id?'PUT':'POST',{name:hook.value.name,active:hook.value.active,revision:hook.value.revision,mapping:hook.value.mapping,rotate:hook.value.rotate});hook.value={...d.webhook,rotate:false};secret.value=d.token||secret.value;await reload();draftBaseline=draft();notice.value=d.token?'Webhook salvo. Copie o token agora: ele será exibido somente nesta resposta.':'Webhook atualizado.'}
async function validateHook(){let payload;try{payload=JSON.parse(sample.value)}catch{throw new Error('O payload precisa ser um objeto JSON válido.')}if(!payload||typeof payload!=='object'||Array.isArray(payload))throw new Error('Envie um objeto JSON com os dados de um contato.');validated.value=await api(path.value+'/webhook-preview','POST',{mapping:hook.value.mapping,payload})}
async function copy(text){try{await navigator.clipboard.writeText(text);notice.value='Copiado.'}catch{notice.value='Selecione o texto e copie manualmente.'}}
const curl=computed(()=>hook.value?.url?['curl -X POST '+hook.value.url,'  -H "Authorization: Bearer SEU_TOKEN"','  -H "Content-Type: application/json"','  -H "Idempotency-Key: evento-001"',"  --data '"+sample.value.replaceAll("'","'\\''")+"'"].join(' \\\n'):'Salve o webhook para gerar a URL.')
const actions=[['manual','Cadastro manual','Adicione uma pessoa com seus dados.',UserPlus],['existing','Contatos existentes','Escolha pessoas já cadastradas.',Users],['import','Importar planilha','Carregue e confira um arquivo CSV.',Upload],['webhooks','Receber por webhook','Conecte formulários e outros sistemas.',Webhook]]
const drawerTitle=computed(()=>({manual:'Cadastro manual',existing:'Contatos existentes',import:'Importar planilha',fields:'Lista e campos',webhooks:'Receber por webhook'})[drawer.value])
function draft(){return JSON.stringify(drawer.value==='manual'?contact.value:drawer.value==='fields'?edit.value:drawer.value==='webhooks'?hook.value:drawer.value==='existing'?chosen.value:null)}
async function openDrawer(mode){returnFocus=document.activeElement;drawer.value=mode;tab.value=mode;error.value='';notice.value='';if(mode==='manual')newContact();if(mode==='existing'){chosen.value=[];candidateSearch.value='';await run(()=>loadCandidates())}if(mode==='fields')edit.value=JSON.parse(JSON.stringify(detail.value.list));if(mode==='webhooks'&&!detail.value.webhooks.length&&!hook.value)editHook();draftBaseline=draft();await nextTick();drawerEl.value?.querySelector('button')?.focus()}
function closeDrawer(){if(busy.value)return;if(draft()!==draftBaseline&&!window.confirm('Fechar e descartar as alterações deste painel?'))return;if(secret.value&&!window.confirm('Você já copiou o token? Ao fechar, ele não será mais exibido.'))return;drawer.value='';tab.value='contacts';secret.value='';hook.value=null;returnFocus?.focus()}
function trapDrawer(e){if(!drawer.value)return;if(e.key==='Escape'){e.preventDefault();closeDrawer();return}if(e.key!=='Tab')return;const els=[...drawerEl.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(el=>el.getClientRects().length);if(!els.length)return;const a=els[0],z=els.at(-1);if(!drawerEl.value.contains(document.activeElement)){e.preventDefault();a.focus();return}if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}
async function loadCandidates(page=1){candidates.value=(await api(path.value+'/available-contacts?'+new URLSearchParams({page,search:candidateSearch.value}))).contacts}
async function attachExisting(){const result=await api(path.value+'/existing-contacts','POST',{contact_ids:chosen.value});await reload();await loadCandidates(candidates.value.current_page);chosen.value=[];draftBaseline=draft();notice.value=result.added+' contato(s) adicionado(s). Dados, autorizações e retiradas anteriores foram preservados.'}
function toggleTarget(t){const i=hook.value.mapping.findIndex(m=>m.target===t.key);if(i>=0)hook.value.mapping.splice(i,1);else hook.value.mapping.push({target:t.key,source:({'name':'cliente.nome','phone':'cliente.telefone','email':'cliente.email'})[t.key]||'cliente.'+t.key.replace('fields.','')});validated.value=null}
function generateSample(){const payload={};for(const m of hook.value.mapping){if(!/^[A-Za-z_][A-Za-z0-9_]*(?:\.(?:[A-Za-z_][A-Za-z0-9_]*|[0-9]+)){0,9}$/.test(m.source)||m.source.split('.').some(k=>['__proto__','constructor','prototype'].includes(k)))throw new Error('Confira os caminhos dos campos antes de gerar o exemplo.');const parts=m.source.split('.');let obj=payload;for(const key of parts.slice(0,-1)){if(obj[key]!==undefined&&(typeof obj[key]!=='object'||obj[key]===null))throw new Error('Dois caminhos se sobrepõem. Use caminhos distintos.');obj[key]??={};obj=obj[key]}const key=parts.at(-1);if(key in obj)throw new Error('Dois campos usam caminhos sobrepostos.');const field=detail.value.list.fields.find(f=>'fields.'+f.key===m.target);obj[key]=({name:'Ana Souza',phone:'+5511999990001',email:'ana@example.test',source:'Formulário do site',crm_contact_id:'lead-001',consent:false,consent_evidence:'Exemplo de autorização registrada'})[m.target]??(field?.type==='number'?10:field?.type==='boolean'?false:field?.type==='date'?'2026-10-05':'Exemplo')}sample.value=JSON.stringify(payload,null,2);validated.value=null}
watch(drawer,value=>{if(value&&bodyOverflow===null){bodyOverflow=document.body.style.overflow;document.body.style.overflow='hidden'}else if(!value&&bodyOverflow!==null){document.body.style.overflow=bodyOverflow;bodyOverflow=null}})
onBeforeUnmount(()=>{if(bodyOverflow!==null)document.body.style.overflow=bodyOverflow;secret.value='';window.removeEventListener('keydown',trapDrawer)})
onMounted(()=>{window.addEventListener('keydown',trapDrawer);run(load)})
</script>
<template><section class="contact-list-manager"><div v-if="error&&!drawer" class="error" role="alert">{{error}}</div><p v-if="notice&&!drawer" class="lm-notice" role="status">{{notice}}</p>
<template v-if="!detail"><header class="section-heading"><div><span class="eyebrow">CONHEÇA SEU PÚBLICO</span><h1>Listas de contatos</h1><p>Cadastre pessoas, importe arquivos e receba contatos por webhook.</p></div><button v-if="catalog.can_manage" class="primary" @click="creating=!creating"><Plus :size="17"/>Nova lista</button></header><form v-if="creating" class="table-card lm-create" @submit.prevent="run(create)"><label>Nome da lista<input v-model="newList.name" required maxlength="160"></label><label>Uso da lista<select v-model="newList.kind"><option value="automation">Automação MA</option><option value="voice">Voz e WhatsApp</option></select></label><button class="primary" :disabled="busy">Criar lista</button></form><div class="table-card"><div class="table-toolbar"><h3>Todas as listas <span>{{catalog.lists.length}}</span></h3><div class="search"><Search :size="15"/><input aria-label="Buscar listas" v-model="listSearch" placeholder="Buscar lista…"></div></div><div class="lm-scroll"><table><thead><tr><th>Nome</th><th>Contatos ativos</th><th>Uso</th><th></th></tr></thead><tbody><tr v-for="l in filtered" :key="l.kind+'-'+l.id" class="clickable" @click="run(()=>select(l))"><td><button class="lm-list-name" @click.stop="run(()=>select(l))">{{l.name}}</button></td><td>{{l.count}}</td><td><span class="lm-tag">{{kindLabel(l.kind)}}</span></td><td><button class="secondary" :aria-label="'Editar lista '+l.name" @click.stop="run(()=>select(l))">Editar lista <ArrowRight :size="15"/></button></td></tr></tbody></table></div><p v-if="!filtered.length" class="empty-small">Nenhuma lista encontrada.</p></div></template>
<template v-else><header class="lm-header"><button class="secondary" @click="detail=null;secret='';hook=null"><ArrowLeft :size="16"/>Todas as listas</button><div><span class="eyebrow">{{kindLabel(detail.list.kind)}}</span><h1>{{detail.list.name}}</h1></div><button class="secondary" :disabled="busy" @click="run(()=>reload())"><RefreshCw :size="15"/>Atualizar</button></header><div class="lm-list-intro"><p>Monte o público desta lista. Escolha como deseja adicionar os contatos.</p><button class="secondary" @click="openDrawer('fields')"><Settings2 :size="16"/>Lista e campos</button></div><div v-if="catalog.can_manage" class="lm-entry-actions"><button v-for="[key,title,description,icon] in actions" :key="key" @click="openDrawer(key)"><span class="lm-entry-icon"><component :is="icon" :size="21"/></span><strong>{{title}}</strong><small>{{description}}</small><ArrowRight :size="16"/></button></div>
<template v-if="detail"><div class="lm-grid lm-members-grid"><section class="table-card lm-card"><div class="lm-section-title"><h2>Contatos da lista</h2><span>{{detail.members.total}} cadastro(s)</span></div><form class="lm-member-search" @submit.prevent="run(()=>reload())"><input aria-label="Buscar contato na lista" v-model="memberSearch" placeholder="Buscar nome ou telefone"><button class="secondary" :disabled="busy">Buscar</button></form><div class="lm-scroll"><table><thead><tr><th>Contato</th><th>Autorização</th><th>Situação</th><th v-if="catalog.can_manage"></th></tr></thead><tbody><tr v-for="c in detail.members.data" :key="c.id"><td><strong>{{c.name}}</strong><small>{{c.phone||'Sem telefone'}}</small><small>{{c.email}}</small><details v-if="Object.keys(c.fields||{}).length"><summary>Dados adicionais</summary><dl><div v-for="(value,key) in c.fields" :key="key"><dt>{{detail.list.fields.find(f=>f.key===key)?.label||key}}</dt><dd>{{value===null?'—':value}}</dd></div></dl></details></td><td>{{c.consent?'Registrada':'Não registrada'}}<small v-if="c.suppressed_at">Abordagem bloqueada</small></td><td>{{c.status==='active'?'Na lista':'Retirado'}}</td><td v-if="catalog.can_manage"><button class="secondary" :disabled="busy" @click="run(()=>member(c,c.status!=='active'))">{{c.status==='active'?'Retirar':'Reincluir'}}</button></td></tr></tbody></table></div><p v-if="!detail.members.data.length" class="empty-small">Esta lista ainda não tem contatos para exibir.</p><div class="lm-pages"><button class="secondary" :disabled="busy||detail.members.current_page===1" @click="run(()=>reload(detail.members.current_page-1))">Anterior</button><span>{{detail.members.current_page}} / {{detail.members.last_page}}</span><button class="secondary" :disabled="busy||detail.members.current_page>=detail.members.last_page" @click="run(()=>reload(detail.members.current_page+1))">Próxima</button></div><details v-if="detail.removed.length"><summary>Contatos retirados ({{detail.removed.length}})</summary><div v-for="c in detail.removed" class="lm-removed"><span>{{c.name}} · {{c.phone||c.email}}</span><button v-if="catalog.can_manage" class="secondary" :disabled="busy" @click="run(()=>member(c,true))">Reincluir</button></div></details></section>
</div><p class="lm-note">Cadastrar ou importar organiza o público. As jornadas de automação mantêm suas regras de entrada; este cadastro não as inicia automaticamente. Nas listas de voz, os contatos ficam vinculados às campanhas que usam a lista, respeitando pausas, autorizações e limites.</p></template>
<Teleport to="body"><div v-if="drawer" class="lm-drawer-backdrop" @click.self="closeDrawer"><section ref="drawerEl" class="lm-drawer contact-list-manager" role="dialog" aria-modal="true" :aria-label="drawerTitle"><header class="lm-drawer-header"><div><span class="eyebrow">{{detail.list.name}}</span><h2>{{drawerTitle}}</h2></div><button class="secondary" aria-label="Fechar painel da lista" :disabled="busy" @click="closeDrawer"><X :size="20"/></button></header><div class="lm-drawer-body"><div v-if="error" class="error" role="alert">{{error}}</div><p v-if="notice" class="lm-notice" role="status">{{notice}}</p><template v-if="drawer==='manual'"><form v-if="catalog.can_manage" class="table-card lm-card" @submit.prevent="run(saveContact)"><h2>Dados do contato</h2><p>Contatos já cadastrados são vinculados sem sobrescrever dados ou autorizações.</p><label>Nome<input aria-label="Nome do contato" v-model="contact.name" required maxlength="160"></label><div class="lm-two"><label>Telefone<input v-model="contact.phone" :required="detail.list.kind==='voice'" type="tel" placeholder="+55 11 99999-0000"></label><label>E-mail<input v-model="contact.email" type="email" maxlength="200"></label></div><label>Origem<input v-model="contact.source" required maxlength="300"></label><label>ID no CRM (opcional)<input v-model="contact.crm_contact_id" maxlength="160"></label><label v-for="f in detail.list.fields" :key="f.key">{{f.label}}{{f.required?' *':''}}<select v-if="f.type==='boolean'" v-model="contact.fields[f.key]" :required="f.required"><option :value="undefined">Não informado</option><option :value="true">Sim</option><option :value="false">Não</option></select><input v-else v-model="contact.fields[f.key]" :type="f.type==='number'?'number':f.type==='date'?'date':'text'" :step="f.type==='number'?'any':undefined" :required="f.required" maxlength="2000"></label><label class="lm-check"><input type="checkbox" v-model="contact.consent">Tenho autorização para contatar esta pessoa</label><label v-if="contact.consent">Evidência da autorização<textarea v-model="contact.consent_evidence" required minlength="5" maxlength="1000" rows="2" placeholder="Ex.: solicitou contato no formulário de hoje"/></label><button class="primary" :disabled="busy"><Plus :size="16"/>Adicionar à lista</button></form></template><template v-if="drawer==='existing'"><section class="table-card lm-card"><p>Selecione até 100 contatos. A inclusão mantém os dados e a autorização de cada pessoa.</p><form class="lm-member-search" @submit.prevent="run(()=>loadCandidates())"><input aria-label="Buscar contatos existentes" v-model="candidateSearch" placeholder="Buscar nome, telefone ou e-mail" maxlength="160"><button class="secondary" :disabled="busy"><Search :size="16"/>Buscar</button></form><div v-if="candidates" class="lm-existing"><label v-for="c in candidates.data" :key="c.id" :class="{unavailable:!!c.membership}"><input type="checkbox" v-model="chosen" :value="c.id" :disabled="busy||!!c.membership||chosen.length>=100&&!chosen.includes(c.id)"><span><strong>{{c.name}}</strong><small>{{c.phone||c.email||'Sem telefone'}}<template v-if="c.phone&&c.email"> · {{c.email}}</template></small><small>{{c.membership==='active'?'Já está nesta lista':c.membership?'Retirado · reinclua pela lista':c.consent?'Autorização registrada':'Sem autorização registrada'}}<template v-if="c.suppressed_at"> · Abordagem bloqueada</template></small></span></label><p v-if="!candidates.data.length">Nenhum contato encontrado para esta busca.</p><div class="lm-pages"><button class="secondary" :disabled="busy||candidates.current_page===1" @click="run(()=>loadCandidates(candidates.current_page-1))">Anterior</button><span>{{candidates.current_page}} / {{candidates.last_page}}</span><button class="secondary" :disabled="busy||candidates.current_page>=candidates.last_page" @click="run(()=>loadCandidates(candidates.current_page+1))">Próxima</button></div></div><div class="lm-selection-footer"><span>{{chosen.length}} selecionado(s)</span><button class="primary" :disabled="busy||!chosen.length" @click="run(attachExisting)"><Link2 :size="16"/>Adicionar selecionados</button></div></section></template><template v-if="tab==='fields'"><form class="table-card lm-card" @submit.prevent="run(saveFields)"><fieldset :disabled="!catalog.can_manage||busy"><h2>Lista e campos adicionais</h2><label>Nome da lista<input v-model="edit.name" required maxlength="160"></label><p>Nome, telefone, e-mail, origem e ID no CRM já estão disponíveis. Adicione outros dados para preencher manualmente, importar ou mapear no webhook.</p><div v-for="(f,i) in edit.fields" :key="i" class="lm-field-row"><label>Nome exibido<input v-model="f.label" required maxlength="100" placeholder="Empresa"></label><label>Chave do campo<input v-model="f.key" required pattern="[a-z][a-z0-9_]{0,39}" maxlength="40" placeholder="empresa"></label><label>Tipo<select v-model="f.type"><option value="text">Texto</option><option value="number">Número</option><option value="boolean">Sim / não</option><option value="date">Data</option></select></label><label class="lm-check"><input type="checkbox" v-model="f.required">Obrigatório</label><button type="button" class="secondary" :aria-label="'Remover campo '+(f.label||i+1)" @click="edit.fields.splice(i,1)"><Trash2 :size="16"/></button></div><div class="lm-actions"><button type="button" class="secondary" :disabled="edit.fields.length>=20" @click="addField"><Plus :size="16"/>Adicionar campo</button><button class="primary"><Save :size="16"/>Salvar lista e campos</button></div></fieldset></form></template>
<template v-if="tab==='import'"><section class="table-card lm-card"><div class="lm-section-title"><h2>Importar contatos por CSV</h2><button class="secondary" @click="download"><Download :size="15"/>Baixar modelo CSV</button></div><p>CSV em UTF-8, até 2 MB e 1.000 contatos. Selecione o arquivo, relacione as colunas e confira a prévia antes de importar.</p><fieldset :disabled="!catalog.can_manage||busy"><div class="lm-two"><label>Arquivo CSV<input aria-label="Arquivo CSV" type="file" accept=".csv,text/csv" @change="file=$event.target.files[0];run(inspect)"></label><label>Separador<select v-model="delimiter" @change="run(inspect)"><option value=";">Ponto e vírgula (;)</option><option value=",">Vírgula (,)</option><option :value="'\t'">Tabulação</option></select></label></div><template v-if="inspection"><h3>Relacionar colunas</h3><div class="lm-mappings"><label v-for="t in targets" :key="t.key">{{t.label}}<select :aria-label="'Coluna para '+t.label" v-model="columns[t.key]" @change="batch=null"><option value="">Não importar esta coluna</option><option v-for="h in inspection.headers" :key="h">{{h}}</option></select></label></div><label>Origem padrão<input v-model="csvSource" required maxlength="300" @input="batch=null"></label><label class="lm-check"><input type="checkbox" v-model="csvConsent" @change="batch=null">Tenho autorização dos contatos desta importação</label><label v-if="csvConsent">Evidência comum da autorização<textarea v-model="csvEvidence" rows="2" maxlength="1000" @input="batch=null"/></label><p>Se você mapear uma coluna de autorização ou evidência, o valor de cada linha será utilizado. Cadastros existentes mantêm sua autorização anterior.</p><button class="primary" @click="run(preview)">Validar e gerar prévia</button></template></fieldset></section>
<section v-if="batch" class="table-card lm-card"><h2>{{batch.status==='committed'?'Resultado da importação':'Confira antes de importar'}}</h2><div class="lm-summary"><span>{{batch.summary.valid}} válidos</span><span>{{batch.summary.invalid}} inválidos</span><template v-if="batch.status==='committed'"><span>{{batch.summary.created}} novos</span><span>{{batch.summary.preserved}} existentes preservados</span><span>{{batch.summary.added}} adicionados à lista</span><span>{{batch.summary.removed_preserved}} retiradas preservadas</span></template></div><div class="lm-scroll"><table><thead><tr><th>Nome</th><th>Telefone</th><th>E-mail</th><th>Dados adicionais</th></tr></thead><tbody><tr v-for="(c,i) in batch.preview" :key="i"><td>{{c.name}}</td><td>{{c.phone}}</td><td>{{c.email}}</td><td><span v-for="(value,key) in c.fields" :key="key">{{key}}: {{value}} · </span></td></tr></tbody></table></div><ul v-if="batch.errors.length" class="lm-errors"><li v-for="e in batch.errors">Linha {{e.line}}: {{e.message}}</li></ul><p>A prévia mostra até 20 contatos e 100 erros. Linhas inválidas não serão importadas.</p><button v-if="batch.status!=='committed'" class="primary" :disabled="busy||!catalog.can_manage||!batch.summary.valid" @click="run(commit)">Importar {{batch.summary.valid}} contatos válidos</button></section></template>
<template v-if="tab==='webhooks'"><section v-if="detail.webhooks.length||!hook" class="table-card lm-card"><div class="lm-section-title"><div><h2>Webhooks de entrada</h2><p>Receba um contato por evento JSON. Escolha de onde vem cada dado e onde será salvo.</p></div><button v-if="catalog.can_manage" class="primary" @click="editHook()"><Plus :size="16"/>Novo webhook</button></div><div v-for="h in detail.webhooks" :key="h.id" class="lm-hook-item"><div><strong>{{h.name}}</strong><span :class="['status',h.active?'active':'paused']">{{h.active?'Ativo':'Desativado'}}</span><small>{{h.url}}</small></div><button class="secondary" @click="editHook(h)">Configurar</button></div><p v-if="!detail.webhooks.length">Nenhum webhook criado para esta lista.</p></section>
<form v-if="hook" class="table-card lm-card" @submit.prevent="run(saveHook)"><fieldset :disabled="!catalog.can_manage||busy"><h2>{{hook.id?'Configurar webhook':'Novo webhook'}}</h2><div class="lm-two"><label>Nome do webhook<input v-model="hook.name" required maxlength="160"></label><label class="lm-check"><input type="checkbox" v-model="hook.active">Recebimento ativo</label></div><h3>Quais dados você quer receber?</h3><p>Escolha os campos do payload. Outros dados podem ser definidos em Lista e campos.</p><div class="lm-payload-fields"><label v-for="t in targets" :key="t.key"><input type="checkbox" :checked="hook.mapping.some(m=>m.target===t.key)" @change="toggleTarget(t)"><span>{{t.label}}</span></label></div><p>Selecione os campos que o sistema de origem enviará. Nome e um identificador (telefone ou e-mail) são necessários; listas de voz exigem telefone.</p><details class="lm-advanced"><summary>Configurar os caminhos dos campos (opcional)</summary><p>Use caminhos como <code>cliente.nome</code> para adaptar o recebimento ao seu sistema.</p><div v-for="(m,i) in hook.mapping" :key="i" class="lm-map-row"><label>Caminho no JSON<input :aria-label="'Caminho no JSON '+(i+1)" v-model="m.source" required maxlength="160" placeholder="cliente.nome" @input="validated=null"></label><ArrowRight :size="16"/><label>Salvar em<select :aria-label="'Destino do campo '+(i+1)" v-model="m.target" required @change="validated=null"><option v-for="t in targets" :key="t.key" :value="t.key">{{t.label}}</option></select></label><button type="button" class="secondary" :aria-label="'Remover mapeamento '+(i+1)" @click="hook.mapping.splice(i,1);validated=null"><Trash2 :size="15"/></button></div></details><div class="lm-section-title"><h3>Teste o payload</h3><button type="button" class="secondary" @click="run(async()=>generateSample())">Gerar exemplo com estes campos</button></div><label>JSON de exemplo<textarea aria-label="JSON de exemplo" v-model="sample" rows="7" spellcheck="false" @input="validated=null"/></label><button type="button" class="secondary" @click="run(validateHook)">Testar payload sem cadastrar</button><pre v-if="validated" class="lm-code">{{JSON.stringify(validated.contact,null,2)}}</pre><p v-if="validated" class="lm-notice">Exemplo válido. Nenhum contato foi cadastrado.</p><label v-if="hook.id" class="lm-check"><input type="checkbox" v-model="hook.rotate">Gerar novo token ao salvar (invalida o anterior)</label><div class="lm-actions"><button class="primary"><Webhook :size="16"/>{{hook.id?'Salvar alterações':'Gerar webhook'}}</button></div></fieldset>
<section v-if="hook.url" class="lm-hook-access"><h3>Como enviar</h3><label>URL do webhook<div class="lm-copy"><input readonly :value="hook.url"><button type="button" class="secondary" aria-label="Copiar URL" @click="copy(hook.url)"><Copy :size="15"/></button></div></label><div v-if="secret" class="lm-secret"><strong>Copie o token e guarde no sistema que enviará os dados.</strong><p>Ele não será exibido novamente após sair desta tela.</p><div class="lm-copy"><input aria-label="Token gerado" readonly type="password" :value="secret"><button type="button" class="secondary" @click="copy(secret)">Copiar token</button></div></div><p>Envie <code>Authorization: Bearer SEU_TOKEN</code>, <code>Content-Type: application/json</code> e um <code>Idempotency-Key</code> único por evento. Para repetir o mesmo evento, reutilize a chave e o mesmo conteúdo.</p><pre class="lm-code">{{curl}}</pre><button type="button" class="secondary" @click="copy(curl)">Copiar exemplo de requisição</button><p>A URL recebe dados; ela não envia mensagens nem realiza chamadas. Contatos existentes e retiradas anteriores são preservados.</p><h3>Últimos recebimentos aceitos</h3><div class="lm-scroll"><table><thead><tr><th>Evento</th><th>Contato</th><th>Resultado</th><th>Recebido em</th></tr></thead><tbody><tr v-for="e in detail.webhooks.find(h=>h.id===hook.id)?.receipts||[]" :key="e.event_key"><td>{{e.event_key}}</td><td>#{{e.result.contact_id}}</td><td>{{e.result.membership_removed?'Retirada preservada':e.result.created?'Novo cadastro':'Existente preservado'}}</td><td>{{e.created_at}}</td></tr></tbody></table></div><p v-if="!detail.webhooks.find(h=>h.id===hook.id)?.receipts.length">Sem recebimentos aceitos. Validação de exemplo não entra neste histórico.</p></section></form></template>
</div></section></div></Teleport></template></section></template>
